/* History filters and explicit deletion confirmation use the existing app modal. */
let historyView={kind:'all',level:'all',limit:20},historyDeleteRequest=null;
const HISTORY_KINDS={all:'Semua aktivitas',quiz:'Quiz',simulation:'Simulasi',kaiwa:'Kaiwa',book:'Cerita',data:'Tambah data',other:'Lainnya'};
const HISTORY_LEVELS={all:'Semua level',N5:'N5',N4:'N4',A1:'A1',unknown:'Belum tercatat'};
function historyRows(){return GakuHistory.read()}
function historySetFilter(key,value){const allowed=key==='kind'?HISTORY_KINDS:key==='level'?HISTORY_LEVELS:null;if(!allowed||!Object.hasOwn(allowed,value))return;historyView[key]=value;historyView.limit=20;render()}
function historyMore(){historyView.limit+=20;render()}
function historyDate(value,day=false){const t=GakuHistory.stamp(value);return t?new Date(t).toLocaleString('id-ID',day?{dateStyle:'full'}:{dateStyle:'medium',timeStyle:'short'}):'Tanggal belum tercatat'}
function historySummary(r){const v=r.quiz;if(v){const labels={completed:'Selesai',abandoned:'Dihentikan',time:'Waktu habis',lives:'Nyawa habis'};return (Number.isInteger(v.answered)?v.answered+' terjawab · ':'')+(labels[v.reason]||labels[v.status]||'Hasil latihan')}if(r.simulation){const v=r.simulation;return String(r.detail||'').replace(/\s*·\s*\d+\/\d+ benar$/,'')+(Number.isFinite(v.durationSeconds)?' · '+Math.round(v.durationSeconds/60)+' menit':'')}if(r.buku)return String(r.detail||'').replace(/\s*·\s*\d+\/\d+(?: benar)?$/,'');if(r.kaiwa&&Number.isInteger(r.kaiwa.completed)&&Number.isInteger(r.kaiwa.total))return String(r.detail||'')+' · '+r.kaiwa.completed+'/'+r.kaiwa.total+' balasan selesai';return String(r.detail||'Aktivitas belajar')}
function historyCard(r){const kind=GakuHistory.kind(r),level=GakuHistory.level(r),score=GakuHistory.score(r),name=kind==='book'?'Cerita':String(r.type||'Aktivitas belajar');return `<article class="history-card"><div class="history-card-main"><div class="history-badges"><span class="history-kind">${esc(HISTORY_KINDS[kind])}</span><span class="history-level">${esc(level==='unknown'?'Level belum tercatat':level)}</span></div><h3>${esc(name)}</h3><p>${esc(historySummary(r))}</p><time${GakuHistory.stamp(r.time)?` datetime="${esc(r.time)}"`:''}>${esc(historyDate(r.time))}</time></div>${score?`<div class="history-score"><b>${score.correct}<small>/${score.total}</small></b><span>jawaban benar</span></div>`:''}<button class="history-remove" onclick="historyAskDelete('${r.historyId}')" aria-label="Hapus ${esc(name)} — ${esc(historyDate(r.time))}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 10v7M14 10v7"/></svg><span>Hapus</span></button></article>`}
function historyScreen(){const rows=historyRows();historyData=rows;const filtered=rows.filter(r=>(historyView.kind==='all'||GakuHistory.kind(r)===historyView.kind)&&GakuHistory.matchesLevel(r,historyView.level));const visible=filtered.slice(0,historyView.limit),practice=rows.filter(r=>['quiz','simulation'].includes(GakuHistory.kind(r))).length,learning=rows.filter(r=>['book','kaiwa'].includes(GakuHistory.kind(r))).length;let previous='',cards='';for(const r of visible){const day=historyDate(r.time,true);if(day!==previous){cards+=`<h2 class="history-day">${esc(day)}</h2>`;previous=day}cards+=historyCard(r)}return title('Riwayat','Lihat hasil latihan dan langkah belajarmu.')+`<section class="history-page" aria-label="Riwayat aktivitas"><div class="history-top"><div class="history-stats"><div><b>${rows.length}</b><span>Aktivitas tercatat</span></div><div><b>${practice}</b><span>Quiz & simulasi</span></div><div><b>${learning}</b><span>Cerita & Kaiwa</span></div></div><button class="history-clear" onclick="historyAskDeleteAll()" ${rows.length?'':'disabled'}>Hapus semua</button></div><div class="history-filters"><label>Jenis aktivitas<select aria-label="Jenis aktivitas" onchange="historySetFilter('kind',this.value)">${Object.entries(HISTORY_KINDS).map(([k,v])=>`<option value="${k}" ${historyView.kind===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>Level materi<select aria-label="Level aktivitas" onchange="historySetFilter('level',this.value)">${Object.entries(HISTORY_LEVELS).map(([k,v])=>`<option value="${k}" ${historyView.level===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label><p role="status">${filtered.length} aktivitas${filtered.length!==rows.length?' dari '+rows.length:''}</p></div>${GakuHistory.getError()==='read'?'<p class="history-warning" role="alert">Riwayat belum dapat dibaca. Data tersimpan tidak diubah. Coba muat ulang halaman.</p>':''}${visible.length?`<div class="history-timeline">${cards}</div>`:`<div class="history-empty"><span aria-hidden="true">◷</span><h2>${rows.length?'Belum ada yang cocok':'Perjalananmu mulai dari sini'}</h2><p>${rows.length?'Ubah filter untuk melihat aktivitas lainnya.':'Hasil Quiz, Simulasi, latihan Cerita dan Kaiwa akan muncul setelah selesai.'}</p></div>`}${filtered.length>visible.length?'<button class="history-more" onclick="historyMore()">Tampilkan 20 lagi</button>':''}<p class="history-local-note">Hingga ${GakuHistory.LIMIT} aktivitas terbaru tersimpan di perangkat ini. Riwayat lama tanpa informasi level ditandai “Belum tercatat”.</p></section>`}
function historyAskDelete(id){const row=historyRows().find(r=>r.historyId===id);if(!row){toast('Aktivitas ini sudah tidak ada.');render();return}historyDeleteRequest={ids:[id],all:false};modal(`<h2>Hapus aktivitas ini?</h2><p>${esc(row.type||'Aktivitas belajar')} · ${esc(historySummary(row))}</p><p class="hint">${esc(historyDate(row.time))}. Entri ini dihapus dari Riwayat dan tidak bisa dipulihkan.</p><div class="history-dialog-actions"><button class="primary" onclick="closeModal()">Batal</button><button class="history-confirm-delete" onclick="historyConfirmDelete()">Hapus aktivitas</button></div>`,'Hapus aktivitas dari Riwayat')}
function historyAskDeleteAll(){const rows=historyRows();if(!rows.length)return;historyDeleteRequest={ids:rows.map(r=>r.historyId),all:true};modal(`<h2>Hapus ${rows.length} aktivitas?</h2><p>Semua aktivitas yang tercatat saat ini, termasuk yang di luar filter, akan dihapus dari Riwayat perangkat ini.</p><p class="hint">Materi belajar, kosakata buatanmu, dan favorit tetap tersimpan. Penghapusan riwayat tidak bisa dibatalkan.</p><div class="history-dialog-actions"><button class="primary" onclick="closeModal()">Batal</button><button class="history-confirm-delete" onclick="historyConfirmDelete()">Hapus semua</button></div>`,'Hapus semua Riwayat')}
function historyConfirmDelete(){const request=historyDeleteRequest;if(!request)return;const ok=request.all?GakuHistory.removeMany(request.ids):GakuHistory.remove(request.ids[0]);if(!ok&&GakuHistory.getError()!=='missing'){toast('Riwayat belum bisa dihapus. Periksa penyimpanan perangkat, lalu coba lagi.');return}historyDeleteRequest=null;closeModal();render();toast(request.all?'Riwayat sudah dihapus.':'Aktivitas sudah dihapus.')}
